-  return nameData?.value || ``;
+/**
+ * Deep search for isConsentGranted nodes and extract parent key-value pairs
+ * @param obj - The object to search in
+ * @param parentKey - The parent key for tracking hierarchy
+ * @returns Array of consent items with parent key as name and isConsentGranted value
+ */
+const findConsentItems = (obj: any, parentKey: string = ``): ConsentItem[] => {
+  let results: ConsentItem[] = [];
+
+  if (!obj || typeof obj !== `object`) return results;
+
+  // Check if current object has isConsentGranted property
+  if (obj.hasOwnProperty(`isConsentGranted`)) {
+    results.push({
+      key: parentKey,
+      value: obj.isConsentGranted,
+    });
+  }
+
+  // Recursively search in nested objects
+  for (const [key, value] of Object.entries(obj)) {
+    if (typeof value === `object` && value !== null) {
+      const newParentKey = parentKey ? `${parentKey}.${key}` : key;
+      results = results.concat(findConsentItems(value, newParentKey));
+    }
+  }
+
+  return results;
 };

